&lt;p class=&quot;qowt-stl-Heading2 x-scope qowt-word-para-0&quot;&gt;&lt;span class=&quot;qowt-font2-ProximaNova&quot;&gt;&lt;strong&gt;&lt;span id=&quot;E175&quot; class=&quot;qowt-font2-ProximaNova&quot;&gt;Languages:&lt;/span&gt;&lt;span id=&quot;E176&quot; class=&quot;qowt-font2-ProximaNova&quot;&gt; Fluent French &amp;amp; English&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
